from pathlib import Path
root=Path(__file__).resolve().parents[2];changes={}
def add(file,a,b,count=1):
 p=root/file;s=changes.get(p,p.read_text());assert s.count(a)==count,(file,a[:80],s.count(a));changes[p]=s.replace(a,b)
v='godot/scripts/verified_card_rules.gd';g='godot/scripts/game_state.gd'
add(v,'const Cooking := preload("res://scripts/cooking_rules.gd")','const Cooking := preload("res://scripts/cooking_rules.gd")\nconst HairPower := preload("res://scripts/hair_power_rules.gd")')
